const story=document.querySelector('.robot-story'),boards=[...document.querySelectorAll('.board')];document.querySelector('#motion').dataset.height='1400';function fit(){const s=story.clientWidth/1920;boards.forEach(b=>{b.style.height=(+b.dataset.height*s)+'px';b.querySelector('.board-inner').style.transform=`scale(${s})`})}new ResizeObserver(fit).observe(story);fit();
const box=document.querySelector('#original-lightbox'),frame=document.querySelector('.original-motion-frame iframe'),motionButton=document.querySelector('[data-motion]');let last,ready=false,wantedPlay=location.hash==='#motion';
function send(action){frame.contentWindow?.postMessage({type:'robot-original-motion-command',action},location.origin)}motionButton.textContent='播放动效';motionButton.setAttribute('aria-pressed','false');
addEventListener('message',e=>{if(e.source!==frame.contentWindow||e.origin!==location.origin||e.data?.type!=='robot-original-motion-state')return;ready=e.data.ready;motionButton.textContent=e.data.playing?'暂停动效':'播放动效';motionButton.setAttribute('aria-pressed',String(e.data.playing));const status=document.querySelector('[data-motion-status]');if(status)status.textContent=e.data.playing?'正在播放：原主视觉旋转摆动':'已暂停，点击播放查看';if(ready&&wantedPlay){wantedPlay=false;send('play')}});frame.addEventListener('load',()=>send('state'));addEventListener('hashchange',()=>{if(location.hash==='#motion'){if(ready)send('play');else wantedPlay=true}});
document.addEventListener('click',e=>{const image=e.target.closest('[data-image]');if(image){last=image;box.querySelector('img').src=image.dataset.image;box.showModal();return}if(e.target.closest('[data-zoom]')){document.body.classList.toggle('expanded');e.target.closest('button').setAttribute('aria-label',document.body.classList.contains('expanded')?'适应窗口':'放大展板');fit()}if(e.target.closest('[data-motion]')){if(ready)send('toggle');else{wantedPlay=true;motionButton.textContent='正在载入动效…'}}if(e.target.closest('a[href="#motion"]')){wantedPlay=true;if(ready){wantedPlay=false;send('play')}}});box.querySelector('.close').addEventListener('click',()=>box.close());box.addEventListener('click',e=>{if(e.target===box)box.close()});box.addEventListener('close',()=>last?.focus());
